from pathlib import Path
import re

path=Path('vision-sync.js')
text=path.read_text('utf-8')
text=text.replace("const CONTRACT='ANCHOR_FREE_STRUCTURAL_V7';","const CONTRACT='ANCHOR_FREE_STRUCTURAL_V8';")

normalizer=r'''function normalizedGrayOnly(canvas){const w=canvas.width,h=canvas.height,rgba=canvas.getContext('2d',{willReadFrequently:true}).getImageData(0,0,w,h).data,raw=new Float32Array(w*h),sample=[];for(let i=0,p=0;i<raw.length;i++,p+=4){raw[i]=rgba[p]*.299+rgba[p+1]*.587+rgba[p+2]*.114;if(i%43===0)sample.push(raw[i])}const p10=percentile(sample,.10),p90=percentile(sample,.90),range=Math.max(18,p90-p10),gray=new Float32Array(w*h);for(let i=0;i<gray.length;i++)gray[i]=clamp((raw[i]-p10)/range,0,1);return{w,h,gray,contrast:range/255}}
'''
if 'function normalizedGrayOnly(' not in text:
    text=text.replace('function structuralField(',normalizer+'function structuralField(',1)

old="return{...grid,full:grid.canvas,small,factor,field:structuralField(small)}"
new="return{...grid,full:grid.canvas,small,factor,field:structuralField(small),fullGray:normalizedGrayOnly(grid.canvas)}"
if old not in text:
    raise SystemExit('coarseAtlas return target not found')
text=text.replace(old,new,1)

coarse=r'''async function coarseMatch(info,cfg){const atlas=await coarseAtlas(cfg),thumb=atlas.field,field=atlas.fullGray,factor=atlas.factor,stride=cfg.width===32768?7:4,radii=cfg.width===32768?[6,9,13,18,25,34]:[5,8,12,17,24],angles=[0,45,90,135,180,225,270,315],topByRadius=new Map(radii.map(r=>[r,[]]));let bestSeen=0,rows=0;for(let y=stride;y<thumb.h-stride;y+=stride){for(let x=stride;x<thumb.w-stride;x+=stride){const xf=x*factor,yf=y*factor,target=pixelToGlobal(xf,yf,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const radius of radii)for(const angle of angles){const recall=warpIntensityNccFast(info.field,field,xf,yf,radius*factor,angle,6);if(recall.score<0)continue;pushTop(topByRadius.get(radius),{x,y,radius,angle,score:recall.score,intensityScore:recall.score,intensityNcc:recall.ncc},120);bestSeen=Math.max(bestSeen,recall.score)}}rows++;if(rows%5===0){state.coarseScore=bestSeen;setDiag('SEARCH',`global full-res recall ${Math.round(y/thumb.h*100)}%`,'coarse-global');await sleep(0)}}const seeds=[];for(const radius of radii){const pool=topByRadius.get(radius)||[];for(const item of pool.slice(0,90)){const xf=item.x*factor,yf=item.y*factor,rf=item.radius*factor,structural=scaleAwareStructuralScore(info.field,field,xf,yf,rf,item.angle,4),recall=warpIntensityNccFast(info.field,field,xf,yf,rf,item.angle,4);item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.14*Math.max(0,recall.score)+.86*Math.max(0,structural.score)}pool.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const chosen=[];for(const item of pool){if(chosen.every(seed=>Math.hypot(item.x-seed.x,item.y-seed.y)>=Math.max(11,radius*.50))){chosen.push(item);seeds.push(item);if(chosen.length>=8)break}}}seeds.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));if(!seeds.length)return null;const hypotheses=[];for(const seed of seeds.slice(0,36)){const recallTop=[];for(let y=seed.y-stride*1.6;y<=seed.y+stride*1.6;y+=2)for(let x=seed.x-stride*1.6;x<=seed.x+stride*1.6;x+=2){const xf=x*factor,yf=y*factor,target=pixelToGlobal(xf,yf,COARSE_Z,cfg);if(!inGlobalBounds(target))continue;for(const rf of [.86,.92,.97,1,1.03,1.08,1.14])for(const da of [-18,-12,-6,0,6,12,18]){const radius=seed.radius*rf,angle=angleNorm(seed.angle+da),recall=warpIntensityNccFast(info.field,field,xf,yf,radius*factor,angle,5);pushTop(recallTop,{x,y,radius,angle,score:recall.score,intensityScore:recall.score},56)}}for(const item of recallTop.slice(0,42)){const xf=item.x*factor,yf=item.y*factor,rf=item.radius*factor,structural=scaleAwareStructuralScore(info.field,field,xf,yf,rf,item.angle,3),recall=warpIntensityNccFast(info.field,field,xf,yf,rf,item.angle,3);item.scaleScore=structural.score;item.intensityScore=recall.score;item.rankScore=.10*Math.max(0,recall.score)+.90*Math.max(0,structural.score)}recallTop.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));hypotheses.push(recallTop[0]||seed);await sleep(0)}hypotheses.sort((a,b)=>(b.rankScore??b.score)-(a.rankScore??a.score));const best=hypotheses[0],second=hypotheses.find(x=>x!==best&&Math.hypot(x.x-best.x,x.y-best.y)>=Math.max(12,best.radius*.48)),margin=second?(best.rankScore??best.scaleScore)-(second.rankScore??second.scaleScore):(best.rankScore??best.scaleScore);return{...best,score:best.scaleScore??0,margin,atlas,hypotheses}}'''
text,n=re.subn(r'^async function coarseMatch\(info,cfg\)\{.*$',coarse,text,count=1,flags=re.M)
assert n==1,'coarseMatch replacement failed'

selftest=r'''async function selfTest(profile='gfn'){const cfg=MAPS[1],synth=await syntheticRoi(profile),info=roiSamples(synth.canvas),match=await globalMatch(info,cfg),fine=match.fine,coarse=match.coarse,scale=fine?.scaleFromCoarse||1,actual=fine?{x:fine.globalX/scale,y:fine.globalY/scale,radius:fine.radius/scale,angle:fine.angle}:null,error=actual?Math.hypot(actual.x-synth.expected.x,actual.y-synth.expected.y):Infinity,rotationError=actual?Math.min(angleDiff(actual.angle,synth.angle),angleDiff(angleNorm(actual.angle+180),synth.angle)):Infinity,gateReason=matchGate(coarse,fine,info,cfg),atlas=coarse?.atlas||await coarseAtlas(cfg),truthStructural=scaleAwareStructuralScore(info.field,atlas.fullGray,synth.expected.x*atlas.factor,synth.expected.y*atlas.factor,synth.radius*atlas.factor,synth.angle,2),truthRecall=warpIntensityNccFast(info.field,atlas.fullGray,synth.expected.x*atlas.factor,synth.expected.y*atlas.factor,synth.radius*atlas.factor,synth.angle,2),truthStructuralInv=scaleAwareStructuralScore(info.field,atlas.fullGray,synth.expected.x*atlas.factor,synth.expected.y*atlas.factor,synth.radius*atlas.factor,angleNorm(-synth.angle),2),truthRecallInv=warpIntensityNccFast(info.field,atlas.fullGray,synth.expected.x*atlas.factor,synth.expected.y*atlas.factor,synth.radius*atlas.factor,angleNorm(-synth.angle),2);return{ok:!!actual&&error<=10&&rotationError<=28&&!gateReason,profile,gateReason,error,rotationError,score:fine?.score??-1,scaleScore:fine?.scaleScore??-1,intensityScore:fine?.intensityScore??-1,verifyScore:fine?.verifyScore??-1,margin:fine?.margin??0,coarseScore:coarse?.score??-1,coarseMargin:coarse?.margin??0,truth:{scaleScore:truthStructural.score,gradient:truthStructural.gradient,topology:truthStructural.topology,edgeF1:truthStructural.edgeF1,negative:truthStructural.negative,intensityScore:truthRecall.score,intensityNcc:truthRecall.ncc,inverseScaleScore:truthStructuralInv.score,inverseIntensityScore:truthRecallInv.score,inverseIntensityNcc:truthRecallInv.ncc,radius:synth.radius,angle:synth.angle},expected:synth.expected,actual,features:info.samples.length,positiveFeatures:info.positiveCount,negativeFeatures:info.negativeCount,contrast:info.contrast}}'''
text,n=re.subn(r"^async function selfTest\(profile='gfn'\)\{.*$",selftest,text,count=1,flags=re.M)
assert n==1,'selfTest replacement failed'
path.write_text(text,'utf-8')
